 fn advance_local<'r>(&mut self,input:RetainedCloneRef<'_,u8>,_:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalReceivingPrimary>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalReceivingPrimary>,ValueError>{let d=demand(std::mem::size_of::<Option<u8>>()+std::mem::size_of::<u8>());if !retained_clone_grant_admits(effect.grant(),d)||effect.remaining_work_units()?<1{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}if !effect.performed(1)?{return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"scalar input exceeded original Work").into())))}self.output=Some(*input.get());self.phase=1;Ok(reply.complete(Ok(RetainedCloneStep::Complete(progress(d.copy_bytes)))))}
 fn advance_pending(&self)->bool{self.take_pending}fn output_ready(&self)->bool{!self.closing&&self.output.is_some()}
 fn take_demand(&self)->Result<RetirementDemand,ValueError>{Ok(demand(2*std::mem::size_of::<Option<u8>>()+2*std::mem::size_of::<bool>()))}fn take_work_demand(&self)->Result<u64,ValueError>{Ok(2)}
 fn take<'r>(&mut self,output:&mut Option<u8>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalReceivingPrimary>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalReceivingPrimary>,ValueError>{let d=self.take_demand()?;if output.is_some()||self.output.is_none(){return Ok(reply.complete(Err(ValueError::invariant("scalar output changed").into())))}if !retained_clone_grant_admits(effect.grant(),d)||effect.remaining_work_units()?<1{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}if !effect.performed(1)?{return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"scalar output exceeded original Work").into())))}TAKE_CALLS.fetch_add(1,std::sync::atomic::Ordering::SeqCst);self.take_pending=true;Ok(reply.pending())}
