fn settle<E:NativeReceivingEffectError>(bank:&mut Bank,native:&mut NativeDecodeControl<'_>,frame:&mut NativeReceivingEffect<E>){let demand=frame.resident_success_ack_demand().unwrap();assert!(demand.copy_bytes<=4096);let mut meta=NativeReceivingEffect::<ValueError>::default();let mut authority=OriginalEffectAuthority::new(Ack::<E>(std::marker::PhantomData));let mut output=None;let turn=bank.run(native,|control|control.receive_original_effect(demand,1,&mut meta,&mut authority,|_,effect,owner,action|owner.drive(&mut (frame,&mut output),effect,action))).unwrap();match turn{NativeReceivingEffectPoll::Complete(turn)=>{turn.result.unwrap();},NativeReceivingEffectPoll::Pending{..}=>panic!("success acknowledgement pending")};assert!(output.is_some());assert!(authority.into_producer().is_ok());}
#[test]
fn issued_shared_receiver_binds_and_closes_the_original_input(){
 let law:serde_json::Value=serde_json::from_str(include_str!("source-bank.json")).unwrap();let mut bank=Bank::from_stock(&law["stock"],false);let mut source=RetainedCloneSource::<u8>::from_owner(law["input"].as_u64().unwrap()as u8);let original=source.borrow();let identity=original.reference_identity();let mut receiver=Receiver::new(false);let mut observer=|_|true;let mut recipient=NativeDecodeRetirementRecipient::new();let mut native=NativeDecodeControl::new(law["stock"]["capacityBytes"].as_u64().unwrap()as usize,&mut observer);native.install_retirement_recipient(&mut recipient).unwrap();let d=receiver.demands(original,4096,16).unwrap();assert!(d.copy_bytes<=law["maximumCopyBytes"].as_u64().unwrap()as usize);assert!(matches!(receiver.select_advance(original,4096,16).unwrap(),NativeAdvanceSelection::Local{..}));let mut frame=NativeReceivingEffect::<OriginalReceivingPrimary>::default();let mut authority=OriginalEffectAuthority::new(Local::default());
 let denied=bank.run(&mut native,|control|control.receive_original_effect(d,0,&mut frame,&mut authority,|_,effect,owner,action|owner.drive(&mut (&mut receiver,original),effect,action))).unwrap();match denied{NativeReceivingEffectPoll::Complete(turn)=>{assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default())},_=>panic!("zero-Work bind pending")};assert_eq!(receiver.demands(original,4096,16).unwrap(),d);assert_eq!(original.reference_identity(),identity);
 let state=bank.run(&mut native,|control|control.receive_original_effect_retained(d,1,&mut frame,&mut authority,&mut (&mut receiver,original))).unwrap();assert!(matches!(state,NativeReceivingEffectState::Ready{..}));settle(&mut bank,&mut native,&mut frame);assert!(authority.into_producer().is_ok());assert_eq!(original.reference_identity(),identity);
 let mut frame=NativeReceivingEffect::<OriginalRetirementFailure>::default();let mut close=OriginalEffectAuthority::new(Close);let d=receiver.begin_close_demand().unwrap();assert!(matches!(bank.run(&mut native,|control|control.receive_original_effect_retained(d,1,&mut frame,&mut close,&mut (&mut receiver,true))).unwrap(),NativeReceivingEffectState::Ready{..}));settle(&mut bank,&mut native,&mut frame);for _ in 0..law["maximumTurns"].as_u64().unwrap(){if receiver.terminal_is_empty(){break}let d=receiver.close_demands(4096).unwrap();assert!(d.copy_bytes<=4096);let work=receiver.close_work_demand(4096).unwrap();assert!(matches!(bank.run(&mut native,|control|control.receive_original_effect_retained(d,work,&mut frame,&mut close,&mut (&mut receiver,false))).unwrap(),NativeReceivingEffectState::Ready{..}));settle(&mut bank,&mut native,&mut frame)}assert!(receiver.terminal_is_empty());assert!(close.into_producer().is_ok());drop(receiver);assert_eq!(u128::from(law["stock"]["fuel"].as_u64().unwrap())-bank.wallet.lock().unwrap().fuel,native.actual_work());for _ in 0..law["maximumTurns"].as_u64().unwrap(){if source.terminal_is_empty(){break}source.close_once().unwrap();}assert!(source.terminal_is_empty());
}

