#[test]
fn issued_shared_receiver_runs_complete_child_and_original_close(){
 let law:serde_json::Value=serde_json::from_str(include_str!("source-bank.json")).unwrap();let mut bank=Bank::from_stock(&law["stock"],false);let mut source=RetainedCloneSource::<u8>::from_owner(law["input"].as_u64().unwrap()as u8);let original=source.borrow();let identity=original.reference_identity();let mut receiver=Receiver::new(false);let mut observer=|_|true;let mut recipient=NativeDecodeRetirementRecipient::new();let mut native=NativeDecodeControl::new(law["stock"]["capacityBytes"].as_u64().unwrap()as usize,&mut observer);native.install_retirement_recipient(&mut recipient).unwrap();let mut frame=NativeReceivingEffect::<OriginalReceivingPrimary>::default();let mut local=OriginalEffectAuthority::new(Local::default());let mut interrupt=true;let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:64};
 for _ in 0..law["maximumTurns"].as_u64().unwrap(){if receiver.output_ready(){break}let d=receiver.demands(original,4096,16).unwrap();assert!(d.copy_bytes<=4096,"original shared action quote {} exceeds 4096",d.copy_bytes);match receiver.select_advance(original,4096,16).unwrap(){NativeAdvanceSelection::Local{work}=>{assert!(work<=16);let state=if interrupt{bank.interrupt_copy.store(true,std::sync::atomic::Ordering::SeqCst);let before=local.inspect(|owner|(owner.calls,owner.recovers));let first=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||bank.run(&mut native,|control|control.receive_original_effect_retained(d,work,&mut frame,&mut local,&mut (&mut receiver,original)))));assert!(first.is_err());let entered=local.inspect(|owner|(owner.calls,owner.recovers));assert_eq!(entered.0-before.0,1);assert_eq!(entered.1-before.1,0);let resumed=bank.run(&mut native,|control|control.receive_original_effect_retained(d,work,&mut frame,&mut local,&mut (&mut receiver,original))).unwrap();let after=local.inspect(|owner|(owner.calls,owner.recovers));assert_eq!(after.0-entered.0,law["postInterruptReplays"].as_u64().unwrap()as usize);assert_eq!(after.1-entered.1,law["postInterruptRecovers"].as_u64().unwrap()as usize);interrupt=false;resumed}else{match std::panic::catch_unwind(std::panic::AssertUnwindSafe(||bank.run(&mut native,|control|control.receive_original_effect_retained(d,work,&mut frame,&mut local,&mut (&mut receiver,original))))){Ok(result)=>result.unwrap(),Err(_)=>{bank.run(&mut native,|control|control.receive_original_effect_retained(d,work,&mut frame,&mut local,&mut (&mut receiver,original))).unwrap()}}};if matches!(state,NativeReceivingEffectState::Ready{..}){settle(&mut bank,&mut native,&mut frame);assert_eq!(receiver.advance_pending(),law["completedLocalPending"].as_bool().unwrap())}else{assert!(receiver.advance_pending());assert!(receiver.begin_close_demand().is_err())}},NativeAdvanceSelection::Nested=>{let turn=bank.run_with_turn(&mut native,|turn,control|Ok(receiver.advance_nested(original,control,turn.witness(),4096,16,grant))).unwrap();if let RetainedWorkPoll::Complete(turn)=turn{turn.result.unwrap();}}}assert_eq!(original.reference_identity(),identity)}assert!(receiver.output_ready(),"original shared output did not complete");assert_eq!(TAKE_CALLS.load(std::sync::atomic::Ordering::SeqCst),law["childTakeCalls"].as_u64().unwrap()as usize);assert_eq!(TAKE_RECOVERS.load(std::sync::atomic::Ordering::SeqCst),law["childTakeRecovers"].as_u64().unwrap()as usize);assert_eq!(CHILD_CALLS.load(std::sync::atomic::Ordering::SeqCst),law["childCloseCalls"].as_u64().unwrap()as usize);assert_eq!(CHILD_RECOVERS.load(std::sync::atomic::Ordering::SeqCst),law["childCloseRecovers"].as_u64().unwrap()as usize);assert!(local.into_producer().is_ok());let mut output=None;let mut take=OriginalEffectAuthority::new(Take);let d=receiver.take_demand().unwrap();let work=receiver.take_work_demand().unwrap();assert!(d.copy_bytes<=4096&&work<=16);assert!(matches!(bank.run(&mut native,|control|control.receive_original_effect_retained(d,work,&mut frame,&mut take,&mut (&mut receiver,&mut output))).unwrap(),NativeReceivingEffectState::Ready{..}));settle(&mut bank,&mut native,&mut frame);assert!(take.into_producer().is_ok());assert_eq!(*output.as_ref().unwrap().get(),law["input"].as_u64().unwrap()as u8);
 let mut frame=NativeReceivingEffect::<OriginalRetirementFailure>::default();let mut close=OriginalEffectAuthority::new(Close);let mut controlled=OriginalEffectAuthority::new(CloseOriginal);let d=receiver.begin_close_demand().unwrap();assert!(matches!(bank.run(&mut native,|control|control.receive_original_effect_retained(d,1,&mut frame,&mut close,&mut (&mut receiver,true))).unwrap(),NativeReceivingEffectState::Ready{..}));settle(&mut bank,&mut native,&mut frame);
 for _ in 0..law["maximumTurns"].as_u64().unwrap(){if receiver.terminal_is_empty(){break}let d=receiver.close_demands(4096).unwrap();assert!(d.copy_bytes<=4096,"original shared close quote {} exceeds 4096",d.copy_bytes);let work=receiver.close_work_demand(4096).unwrap();assert!(work<=16);if receiver.requires_original_birth(){let turn=bank.run(&mut native,|control|control.with_retirement(grant,|funding|funding.with_original_close(|loan|Ok(receiver.close_original_birth_step(loan,grant))))).unwrap();if let RetainedWorkPoll::Complete(turn)=turn{turn.result.unwrap();}continue}let state=if receiver.requires_original_control(){bank.run(&mut native,|control|control.receive_original_effect_retained_with(d,work,&mut frame,&mut controlled,|control,effect,owner,action|control.with_retirement(effect.grant(),|funding|funding.with_original_close(|loan|owner.drive(&mut (&mut receiver,loan),effect,action))))).unwrap()}else{bank.run(&mut native,|control|control.receive_original_effect_retained(d,work,&mut frame,&mut close,&mut (&mut receiver,false))).unwrap()};if matches!(state,NativeReceivingEffectState::Ready{..}){settle(&mut bank,&mut native,&mut frame)}}assert!(receiver.terminal_is_empty(),"original shared close did not complete");assert!(close.into_producer().is_ok());assert!(controlled.into_producer().is_ok());drop(receiver);retire_output(&mut bank,&mut native,&mut output,grant,law["maximumTurns"].as_u64().unwrap());assert_eq!(u128::from(law["stock"]["fuel"].as_u64().unwrap())-bank.wallet.lock().unwrap().fuel,native.actual_work());for _ in 0..law["maximumTurns"].as_u64().unwrap(){if source.terminal_is_empty(){break}source.close_once().unwrap();}assert!(source.terminal_is_empty());
}

#[derive(Clone,Copy)]enum SeedOperation{Reserve,Initialize,Release,Take,Retire}
#[derive(Default)]struct SeedProducer{calls:usize,recovers:usize}
impl OriginalEffectProducer for SeedProducer{
 type Output=RetainedCloneStep;type Failure=ValueError;type Context<'a,'b>=(&'a mut semio_framework_value_native_storage::NativeOwnedStorage<Receiver>,semio_framework_value_native_storage::NativeSeedTemplate<Receiver>,SeedOperation,&'a mut Option<Box<Receiver>>)where 'b:'a;
 fn validate_context<'a,'b>(&self,_:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{Ok(())}fn source_turn<'a,'b>(&self,_:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{None}
 fn receive<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{self.calls+=1;let turn=match c.2{SeedOperation::Reserve=>match c.0.reserve_empty(effect){RetainedWorkPoll::Complete(turn)=>turn,RetainedWorkPoll::Pending{..}=>return Ok(reply.pending())},SeedOperation::Initialize=>c.0.initialize_template(c.1,effect),SeedOperation::Release=>c.0.release(effect),SeedOperation::Take=>match c.0.take_box_into(c.3,effect){RetainedWorkPoll::Complete(turn)=>turn,RetainedWorkPoll::Pending{..}=>return Ok(reply.pending())},SeedOperation::Retire=>{if c.3.is_none(){return Err(ValueError::invariant("vacant receiver output"))}if !effect.performed(1)?{return Err(ValueError::literal(ValueRefusalKind::WorkLimit,"receiver output release exceeded Work"))}drop(c.3.take());RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:std::mem::size_of::<Option<Box<Receiver>>>(),released_bytes:std::mem::size_of::<Receiver>(),..Default::default()})),work:1}}};Ok(reply.complete(turn.result))}
 fn recover<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,_:&mut RetainedAllocationEffect<'_>,_:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{self.recovers+=1;Err(ValueError::invariant("recorded seed action was replayed"))}
}
#[test]
fn original_shared_receiver_seed_respects_per_turn_copy(){
 let law:serde_json::Value=serde_json::from_str(include_str!("source-bank.json")).unwrap();let limit=law["maximumCopyBytes"].as_u64().unwrap()as usize;assert!(semio_framework_value_native_storage::NativeOwnedStorage::<Receiver>::seed_demand().copy_bytes>limit);
 for subset in [false,true]{for cut in law["seedCancelCuts"].as_array().unwrap(){let template=<Receiver as NativeReceiver<u8,Shared>>::seed_template(subset).expect("actual shared receiver template");let mut bank=Bank::from_stock(&law["stock"],false);let mut observer=|_|true;let mut recipient=NativeDecodeRetirementRecipient::new();let mut native=NativeDecodeControl::new(law["stock"]["capacityBytes"].as_u64().unwrap()as usize,&mut observer);native.install_retirement_recipient(&mut recipient).unwrap();let mut storage=semio_framework_value_native_storage::NativeOwnedStorage::<Receiver>::empty();let mut frame=NativeReceivingEffect::<ValueError>::default();let mut producer=OriginalEffectAuthority::new(SeedProducer::default());let mut output=None;let reserve=semio_framework_value_native_storage::NativeOwnedStorage::<Receiver>::reserve_demand();assert!(matches!(bank.run(&mut native,|control|control.receive_original_effect_retained(reserve,1,&mut frame,&mut producer,&mut (&mut storage,template,SeedOperation::Reserve,&mut output))).unwrap(),NativeReceivingEffectState::Ready{..}));settle(&mut bank,&mut native,&mut frame);let address=storage.address();
  for turn in 0..cut.as_u64().unwrap(){let d=storage.template_seed_demand(template).unwrap();assert!(d.copy_bytes<=limit);let before=producer.inspect(|p|(p.calls,p.recovers));let state=if turn==0{bank.interrupt_copy.store(true,std::sync::atomic::Ordering::SeqCst);let first=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||bank.run(&mut native,|control|control.receive_original_effect_retained(d,1,&mut frame,&mut producer,&mut (&mut storage,template,SeedOperation::Initialize,&mut output)))));assert!(first.is_err());let entered=producer.inspect(|p|(p.calls,p.recovers));let resumed=bank.run(&mut native,|control|control.receive_original_effect_retained(d,1,&mut frame,&mut producer,&mut (&mut storage,template,SeedOperation::Initialize,&mut output))).unwrap();let after=producer.inspect(|p|(p.calls,p.recovers));assert_eq!(entered.0-before.0,1);assert_eq!(after.0-entered.0,law["seedInterruptReplays"].as_u64().unwrap()as usize);assert_eq!(after.1-entered.1,0);resumed}else{bank.run(&mut native,|control|control.receive_original_effect_retained(d,1,&mut frame,&mut producer,&mut (&mut storage,template,SeedOperation::Initialize,&mut output))).unwrap()};assert!(matches!(state,NativeReceivingEffectState::Ready{..}));settle(&mut bank,&mut native,&mut frame);assert_eq!(storage.address(),address);assert!(!storage.initialized());assert!(storage.get().is_none());}
  let d=storage.release_demand();assert!(d.copy_bytes<=limit);assert!(matches!(bank.run(&mut native,|control|control.receive_original_effect_retained(d,1,&mut frame,&mut producer,&mut (&mut storage,template,SeedOperation::Release,&mut output))).unwrap(),NativeReceivingEffectState::Ready{..}));settle(&mut bank,&mut native,&mut frame);assert!(storage.terminal_is_empty());assert!(producer.into_producer().is_ok());assert_eq!(u128::from(law["stock"]["fuel"].as_u64().unwrap())-bank.wallet.lock().unwrap().fuel,native.actual_work());}}
}

#[test]fn original_shared_receiver_field_template_completes_and_releases(){let law:serde_json::Value=serde_json::from_str(include_str!("source-bank.json")).unwrap();let limit=law["maximumCopyBytes"].as_u64().unwrap()as usize;for subset in [false,true]{let template=<Receiver as NativeReceiver<u8,Shared>>::seed_template(subset).unwrap();let mut bank=Bank::from_stock(&law["stock"],false);let mut observer=|_|true;let mut recipient=NativeDecodeRetirementRecipient::new();let mut native=NativeDecodeControl::new(law["stock"]["capacityBytes"].as_u64().unwrap()as usize,&mut observer);native.install_retirement_recipient(&mut recipient).unwrap();let mut storage=semio_framework_value_native_storage::NativeOwnedStorage::<Receiver>::empty();let mut output=None;let mut frame=NativeReceivingEffect::<ValueError>::default();let mut producer=OriginalEffectAuthority::new(SeedProducer::default());let reserve=semio_framework_value_native_storage::NativeOwnedStorage::<Receiver>::reserve_demand();assert!(matches!(bank.run(&mut native,|control|control.receive_original_effect_retained(reserve,1,&mut frame,&mut producer,&mut (&mut storage,template,SeedOperation::Reserve,&mut output))).unwrap(),NativeReceivingEffectState::Ready{..}));settle(&mut bank,&mut native,&mut frame);let address=storage.address();for _ in 0..law["maximumTurns"].as_u64().unwrap(){if storage.initialized(){break}let d=storage.template_seed_demand(template).unwrap();assert!(d.copy_bytes<=limit);assert!(matches!(bank.run(&mut native,|control|control.receive_original_effect_retained(d,1,&mut frame,&mut producer,&mut (&mut storage,template,SeedOperation::Initialize,&mut output))).unwrap(),NativeReceivingEffectState::Ready{..}));settle(&mut bank,&mut native,&mut frame);assert_eq!(storage.address(),address)}assert!(storage.initialized());assert!(storage.get().unwrap().terminal_is_empty());let d=semio_framework_value_native_storage::NativeOwnedStorage::<Receiver>::box_demand();assert!(matches!(bank.run(&mut native,|control|control.receive_original_effect_retained(d,1,&mut frame,&mut producer,&mut (&mut storage,template,SeedOperation::Take,&mut output))).unwrap(),NativeReceivingEffectState::Ready{..}));settle(&mut bank,&mut native,&mut frame);assert_eq!(Some(output.as_ref().unwrap().as_ref()as*const Receiver as usize),address);let d=RetirementDemand{copy_bytes:std::mem::size_of::<Option<Box<Receiver>>>(),release_bytes:std::mem::size_of::<Receiver>(),depth:1,..Default::default()};assert!(matches!(bank.run(&mut native,|control|control.receive_original_effect_retained(d,1,&mut frame,&mut producer,&mut (&mut storage,template,SeedOperation::Retire,&mut output))).unwrap(),NativeReceivingEffectState::Ready{..}));settle(&mut bank,&mut native,&mut frame);assert!(output.is_none()&&storage.terminal_is_empty());assert!(producer.into_producer().is_ok());assert_eq!(u128::from(law["stock"]["fuel"].as_u64().unwrap())-bank.wallet.lock().unwrap().fuel,native.actual_work());}}

type Shared=semio_framework_value_shared_issuance::SealedShared<u8>;
struct Take;
impl OriginalEffectProducer for Take{
 type Output=RetainedCloneStep;type Failure=OriginalReceivingPrimary;type Context<'a,'b>=(&'a mut Receiver,&'a mut Option<Shared>)where 'b:'a;
 fn validate_context<'a,'b>(&self,_:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{Ok(())}fn source_turn<'a,'b>(&self,_:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{None}
 fn receive<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{c.0.take(c.1,effect,reply)}
 fn recover<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{c.0.recover_take(c.1,effect,reply)}
}
struct OutputClose;
impl OriginalEffectProducer for OutputClose{
 type Output=RetainedCloneStep;type Failure=OriginalRetirementFailure;type Context<'a,'b>=(&'a mut Option<Shared>,&'a mut semio_framework_value_native_shared_engine::retained_clone::RetainedCloneClose,Option<&'a mut OriginalRetirementCloseLoan<'b>>)where 'b:'a;
 fn validate_context<'a,'b>(&self,_:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{Ok(())}fn source_turn<'a,'b>(&self,_:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{None}
 fn receive<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{if c.1.is_empty(){let turn=c.1.begin_granted(c.0,effect);return Ok(reply.complete(turn.result.map(|step|RetainedCloneStep::Progress(step.map_or_else(Default::default,|step|step.progress()))).map_err(Into::into)))}match c.2.as_deref_mut(){Some(original)=>c.1.step_original_into(original,4096,effect,reply),None=>c.1.step_into(4096,effect,reply)}}
 fn recover<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{match c.2.as_deref_mut(){Some(original)=>c.1.recover_step_original_into(original,4096,effect,reply),None=>c.1.recover_step_into(4096,effect,reply)}}
}
fn retire_output(bank:&mut Bank,native:&mut NativeDecodeControl<'_>,output:&mut Option<Shared>,grant:RetainedCloneGrant,limit:u64){let mut retirement=semio_framework_value_native_shared_engine::retained_clone::RetainedCloneClose::default();let mut authority=OriginalEffectAuthority::new(OutputClose);let mut frame=NativeReceivingEffect::<OriginalRetirementFailure>::default();for _ in 0..limit{if output.is_none()&&retirement.is_empty(){break}if retirement.requires_original_birth(){let turn=bank.run(native,|control|control.with_retirement(grant,|funding|funding.with_original_close(|loan|Ok(retirement.step_original_birth(loan,grant))))).unwrap();if let RetainedWorkPoll::Complete(turn)=turn{turn.result.unwrap();}continue}let d=retirement.next_owner_demands::<Shared>(output.is_some(),&None,4096).unwrap();let work=retirement.next_owner_work::<Shared>(output.is_some(),&None,4096).unwrap();assert!(d.copy_bytes<=4096&&work<=16);let state=if retirement.requires_original_control(){bank.run(native,|control|control.receive_original_effect_retained_with(d,work,&mut frame,&mut authority,|control,effect,owner,action|control.with_retirement(effect.grant(),|funding|funding.with_original_close(|loan|owner.drive(&mut (output,&mut retirement,Some(loan)),effect,action))))).unwrap()}else{bank.run(native,|control|control.receive_original_effect_retained(d,work,&mut frame,&mut authority,&mut (output,&mut retirement,None))).unwrap()};if matches!(state,NativeReceivingEffectState::Ready{..}){settle(bank,native,&mut frame)}}assert!(output.is_none()&&retirement.is_empty());assert!(authority.into_producer().is_ok());}


#[test]fn vacant_receiving_frame_fields_are_individually_bounded(){let law:serde_json::Value=serde_json::from_str(include_str!("source-bank.json")).unwrap();type Frame=NativeReceivingEffect<OriginalRetirementFailure>;let mut raw=std::mem::MaybeUninit::<Frame>::uninit();let count=Frame::vacant_field_count();assert_eq!(count,law["vacantFrameFields"].as_u64().unwrap()as usize);for index in 0..count{let size=unsafe{Frame::vacant_field_size(&mut raw,index)}.unwrap();assert!(size<=law["maximumCopyBytes"].as_u64().unwrap()as usize);assert!(unsafe{Frame::write_vacant_field(&mut raw,index)});}assert_eq!(unsafe{Frame::vacant_field_size(&mut raw,count)},None);assert!(!unsafe{Frame::write_vacant_field(&mut raw,count)});let frame=unsafe{raw.assume_init()};assert!(!frame.has_pending_recovery());drop(frame);}

