impl OriginalEffectProducer for NestedLocal{type Output=RetainedCloneStep;type Failure=OriginalReceivingPrimary;type Context<'a,'b>=(&'a mut NestedReceiver,RetainedCloneRef<'b,u8>)where 'b:'a;fn validate_context<'a,'b>(&self,_:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{Ok(())}fn source_turn<'a,'b>(&self,_:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{None}fn receive<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{self.calls+=1;c.0.advance_local(c.1,4096,effect,reply)}fn recover<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{self.recovers+=1;c.0.recover_advance_local(c.1,4096,effect,reply)}}
struct NestedClose;
impl OriginalEffectProducer for NestedClose{type Output=RetainedCloneStep;type Failure=OriginalRetirementFailure;type Context<'a,'b>=(&'a mut NestedReceiver,bool,Option<&'a mut OriginalRetirementCloseLoan<'b>>)where 'b:'a;fn validate_context<'a,'b>(&self,_:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{Ok(())}fn source_turn<'a,'b>(&self,_:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{None}fn receive<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{if c.1{return c.0.begin_close_into(effect,reply)}match c.2.as_deref_mut(){Some(loan)=>c.0.close_original_step(loan,4096,effect,reply),None=>c.0.close_step(4096,effect,reply)}}fn recover<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{if c.1{return c.0.recover_begin_close_into(effect,reply)}match c.2.as_deref_mut(){Some(loan)=>c.0.recover_close_original_step(loan,4096,effect,reply),None=>c.0.recover_close_step(4096,effect,reply)}}}
#[test]fn nested_shared_receiver_cancels_partial_seed_after_recorded_post_unwind(){let law:serde_json::Value=serde_json::from_str(include_str!("source-bank.json")).unwrap();let mut bank=Bank::from_stock(&law["stock"],false);let mut source=RetainedCloneSource::<u8>::from_owner(law["input"].as_u64().unwrap()as u8);let original=source.borrow();let identity=original.reference_identity();let mut receiver=NestedReceiver::new(false);let mut observer=|_|true;let mut recipient=NativeDecodeRetirementRecipient::new();let mut native=NativeDecodeControl::new(law["stock"]["capacityBytes"].as_u64().unwrap()as usize,&mut observer);native.install_retirement_recipient(&mut recipient).unwrap();let mut frame=NativeReceivingEffect::<OriginalReceivingPrimary>::default();let mut authority=OriginalEffectAuthority::new(NestedLocal::default());for index in 0..law["nestedSeedActions"].as_u64().unwrap(){let d=receiver.demands(original,4096,16).unwrap();assert!(d.copy_bytes<=4096);let NativeAdvanceSelection::Local{work}=receiver.select_advance(original,4096,16).unwrap()else{panic!("unexpected nested action before seed")};let state=if index+1==law["nestedSeedActions"].as_u64().unwrap(){bank.interrupt_copy.store(true,std::sync::atomic::Ordering::SeqCst);let before=authority.inspect(|p|(p.calls,p.recovers));let first=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||bank.run(&mut native,|control|control.receive_original_effect_retained(d,work,&mut frame,&mut authority,&mut (&mut receiver,original)))));assert!(first.is_err());let entered=authority.inspect(|p|(p.calls,p.recovers));let resumed=bank.run(&mut native,|control|control.receive_original_effect_retained(d,work,&mut frame,&mut authority,&mut (&mut receiver,original))).unwrap();let after=authority.inspect(|p|(p.calls,p.recovers));assert_eq!(entered.0-before.0,1);assert_eq!(after.0-entered.0,0);assert_eq!(after.1-entered.1,0);resumed}else{bank.run(&mut native,|control|control.receive_original_effect_retained(d,work,&mut frame,&mut authority,&mut (&mut receiver,original))).unwrap()};assert!(matches!(state,NativeReceivingEffectState::Ready{..}));settle(&mut bank,&mut native,&mut frame);assert_eq!(original.reference_identity(),identity)}assert!(!receiver.output_ready());assert!(authority.into_producer().is_ok());let mut frame=NativeReceivingEffect::<OriginalRetirementFailure>::default();let mut close=OriginalEffectAuthority::new(NestedClose);let start=receiver.begin_close_demand().unwrap();assert!(matches!(bank.run(&mut native,|control|control.receive_original_effect_retained(start,1,&mut frame,&mut close,&mut (&mut receiver,true,None))).unwrap(),NativeReceivingEffectState::Ready{..}));settle(&mut bank,&mut native,&mut frame);for _ in 0..law["maximumTurns"].as_u64().unwrap(){if receiver.terminal_is_empty(){break}let d=receiver.close_demands(4096).unwrap();let work=receiver.close_work_demand(4096).unwrap();assert!(d.copy_bytes<=4096);let state=if receiver.requires_original_control(){bank.run(&mut native,|control|control.receive_original_effect_retained_with(d,work,&mut frame,&mut close,|control,effect,owner,action|control.with_retirement(effect.grant(),|funding|funding.with_original_close(|loan|owner.drive(&mut (&mut receiver,false,Some(loan)),effect,action))))).unwrap()}else{bank.run(&mut native,|control|control.receive_original_effect_retained(d,work,&mut frame,&mut close,&mut (&mut receiver,false,None))).unwrap()};if matches!(state,NativeReceivingEffectState::Ready{..}){settle(&mut bank,&mut native,&mut frame)}}assert!(receiver.terminal_is_empty());assert!(close.into_producer().is_ok());drop(receiver);assert_eq!(u128::from(law["stock"]["fuel"].as_u64().unwrap())-bank.wallet.lock().unwrap().fuel,native.actual_work());for _ in 0..law["maximumTurns"].as_u64().unwrap(){if source.terminal_is_empty(){break}source.close_once().unwrap();}assert!(source.terminal_is_empty());}
